#!/bin/bash
# Nightly backup of C2Pass: PostgreSQL (accounts, payments, sessions), MongoDB (questions, copies) and the stored files
# (voice recordings, refund attestations). One folder per backup: backups/YYYYMMDD-HHMMSS/.
#
# Settings, read from .env:
#   BACKUP_PASSPHRASE   encrypts every file (AES-256, openssl). Generated by ops/install.sh. Keep a copy off the server
#                       together with VAULT_KEY and S3_SSE_KEY: without them a backup cannot be read back.
#   BACKUP_S3_BUCKET    off-site copy, e.g. "c2pass-backups" (AWS S3, Cloudflare R2, Backblaze B2, OVH Object Storage)
#   BACKUP_S3_ENDPOINT  for a non-AWS provider, e.g. https://<account>.r2.cloudflarestorage.com
#   BACKUP_S3_ACCESS_KEY_ID / BACKUP_S3_SECRET_ACCESS_KEY / BACKUP_S3_REGION (default auto)
#   KEEP_DAYS           local retention, 14 days by default
# Usage, from the installation folder: ops/backup.sh [destination]   (installed as a nightly cron by ops/install.sh)
set -euo pipefail
cd "$(dirname "$0")/.."
DEST=${1:-./backups}
COMPOSE=${COMPOSE:-docker compose -f docker-compose.yml -f docker-compose.prod.yml}
env_value() { [ -f .env ] && grep "^$1=" .env | head -1 | cut -d= -f2- || true; }
PASSPHRASE=${BACKUP_PASSPHRASE:-$(env_value BACKUP_PASSPHRASE)}
BUCKET=${BACKUP_S3_BUCKET:-$(env_value BACKUP_S3_BUCKET)}
KEEP_DAYS=${KEEP_DAYS:-14}
umask 077   # backups hold personal data: readable by root only
DIR="$DEST/$(date -u +%Y%m%d-%H%M%S)"
mkdir -p "$DIR"

# Encrypts stdin to the given file when a passphrase is set, else writes it as is.
store() {
  if [ -n "$PASSPHRASE" ]; then BACKUP_PASSPHRASE="$PASSPHRASE" openssl enc -aes-256-cbc -salt -pbkdf2 -iter 200000 -pass env:BACKUP_PASSPHRASE -out "$1.enc"
  else cat > "$1"; fi
}

$COMPOSE exec -T postgres pg_dump -U c2pass -d c2pass_tcf --format=custom --no-owner | store "$DIR/postgres.dump"
$COMPOSE exec -T mongo mongodump --quiet --archive --gzip --db="${MONGO_DB:-c2pass}" | store "$DIR/mongo.archive.gz"
$COMPOSE exec -T s3 tar czf - -C /data . | store "$DIR/files.tar.gz"

# A dump that is suspiciously small means a command failed half-way: say so loudly.
for f in "$DIR"/postgres.dump* "$DIR"/mongo.archive.gz*; do
  [ "$(wc -c < "$f")" -gt 1000 ] || { echo "ÉCHEC : sauvegarde vide ou incomplète : $f" >&2; exit 1; }
done

if [ -n "$BUCKET" ]; then
  ENDPOINT=$(env_value BACKUP_S3_ENDPOINT); REGION=$(env_value BACKUP_S3_REGION)
  docker run --rm -v "$(cd "$DIR" && pwd):/backup:ro" \
    -e AWS_ACCESS_KEY_ID="$(env_value BACKUP_S3_ACCESS_KEY_ID)" -e AWS_SECRET_ACCESS_KEY="$(env_value BACKUP_S3_SECRET_ACCESS_KEY)" \
    -e AWS_DEFAULT_REGION="${REGION:-auto}" \
    amazon/aws-cli:2.22.35 s3 cp --recursive --only-show-errors /backup "s3://$BUCKET/$(basename "$DIR")/" ${ENDPOINT:+--endpoint-url "$ENDPOINT"}
  echo "Copie hors site : s3://$BUCKET/$(basename "$DIR")/"
fi

find "$DEST" -mindepth 1 -maxdepth 1 -type d -name '20*' -mtime +"$KEEP_DAYS" -exec rm -rf {} +
echo "Sauvegarde OK : $DIR ($(du -sh "$DIR" | cut -f1)$([ -n "$PASSPHRASE" ] && echo ', chiffrée'))"
